// Find all border halfedges
std::vector<Halfedge_handle> border_edges;
for (auto h = poly.halfedges_begin(); h != poly.halfedges_end(); ++h) {
    if (h->is_border_edge()) {
        border_edges.push_back(h);
    }
}

// Group border edges into holes (connected cycles)
std::vector<std::vector<Vertex_handle>> holes;
for (auto h : border_edges) {
    if (visited) continue;
    std::vector<Vertex_handle> hole;
    Halfedge_handle current = h;
    do {
        hole.push_back(current->vertex());
        current = current->next();
    } while (current != h && !current->is_border());
    if (hole.size() >= 3) {
        holes.push_back(hole);
    }
}

// For each hole, triangulate using ear clipping or fan triangulation
for (auto& hole : holes) {
    if (hole.size() < 3) continue;

    // Simple fan triangulation from first vertex
    Vertex_handle v0 = hole[0];
    for (size_t i = 1; i + 1 < hole.size(); ++i) {
        poly.make_triangle(v0, hole[i], hole[i + 1]);
    }
}

